return ['domain'=>'reportedip-hive','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'es','project-id-version'=>'ReportedIP Hive Light 1.3.8','pot-creation-date'=>'2026-10-11T08:20:06+00:00','po-revision-date'=>'2026-10-11T08:20:06+00:00','messages'=>['ReportedIP Hive Light'=>'ReportedIP Hive Light','https://reportedip.com/products/wordpress-plugin/'=>'https://reportedip.com/products/wordpress-plugin/','Lightweight brute-force login protection with optional community-powered IP reputation checks.'=>'Protección ligera de inicio de sesión contra ataques de fuerza bruta, con consultas opcionales de reputación de IP impulsadas por la comunidad.','Patrick Schlesinger'=>'Patrick Schlesinger','https://reportedip.com'=>'https://reportedip.com','Dashboard'=>'Escritorio','Settings'=>'Ajustes','Blocked IPs'=>'IP bloqueadas','Whitelist'=>'Whitelist','Added %s to the whitelist.'=>'%s se ha añadido a la whitelist.','Could not add the entry — please provide a valid IPv4/v6 address or CIDR range.'=>'No se ha podido añadir la entrada. Introduce una dirección IPv4/v6 o un rango CIDR válidos.','Testing connection…'=>'Probando conexión…','Please enter an access key first.'=>'Primero introduce una clave de acceso.','Could not reach reportedip.com. Check your network and try again.'=>'No se ha podido conectar con reportedip.com. Comprueba tu red e inténtalo de nuevo.','Active blocks'=>'Bloqueos activos','Blocks (last 24 h)'=>'Bloqueos (últimas 24 h)','Attempts (last 24 h)'=>'Intentos (últimas 24 h)','Whitelisted IPs'=>'IP en la whitelist','Last 24 h'=>'Últimas 24 h','Last 7 days'=>'Últimos 7 días','Last 30 days'=>'Últimos 30 días','All time'=>'Desde siempre','Defended attacks'=>'Ataques repelidos','Each block represents one IP that was prevented from logging in after exceeding the configured thresholds.'=>'Cada bloqueo corresponde a una IP a la que se impidió iniciar sesión tras superar los umbrales configurados.','Operation mode'=>'Modo de funcionamiento','Community Network'=>'Community Network','IP reputation lookups + queued reports active.'=>'Consultas de reputación de IP + cola de informes activas.','Local Shield'=>'Local Shield','No external requests. Switch to Community Network in Settings to enable reputation lookups.'=>'Sin peticiones externas. Cambia a Community Network en Ajustes para activar las consultas de reputación.','API health & quota'=>'Estado y cuota de la API','Outbound calls this hour: %1$d / %2$d'=>'Llamadas salientes en esta hora: %1$d / %2$d','Rolling 1-hour window. When exhausted, reputation lookups are skipped (login still proceeds, fail-open).'=>'Ventana móvil de 1 hora. Si se agota, se omiten las consultas de reputación (el inicio de sesión continúa, fail-open).','Report queue'=>'Cola de informes','pending'=>'pendiente','processing'=>'en proceso','completed'=>'completado','failed'=>'fallido','Reports are queued in the database and dispatched by a 15-minute cron job — never from the login path. Failed rows retry up to 3 times.'=>'Los informes se guardan en cola en la base de datos y los envía un cron cada 15 minutos, nunca desde el proceso de inicio de sesión. Las filas fallidas se reintentan hasta 3 veces.','Recent activity'=>'Actividad reciente','No login attempts recorded yet.'=>'Todavía no se ha registrado ningún intento de inicio de sesión.','Connection'=>'Conexión','Protection'=>'Protección','Privacy'=>'Privacidad','Brute-force protection for WordPress logins'=>'Protección contra ataques de fuerza bruta para el inicio de sesión de WordPress','Save Changes'=>'Guardar cambios','Blocked IP addresses'=>'Direcciones IP bloqueadas','IP whitelist'=>'Whitelist de IP','Add to whitelist'=>'Añadir a la whitelist','IP address or CIDR range'=>'Dirección IP o rango CIDR','IPv4, IPv6 or IPv4 CIDR (e.g. 203.0.113.0/24).'=>'IPv4, IPv6 o CIDR IPv4 (p. ej. 203.0.113.0/24).','Reason (optional)'=>'Motivo (opcional)','e.g. Office VPN'=>'p. ej. VPN de la oficina','Expires (optional)'=>'Caduca (opcional)','Leave blank for a permanent entry.'=>'Déjalo en blanco para una entrada permanente.','Current whitelist'=>'Whitelist actual','No whitelist entries yet.'=>'Todavía no hay entradas en la whitelist.','Insufficient permissions.'=>'Permisos insuficientes.','Invalid IP address.'=>'Dirección IP no válida.','None — use REMOTE_ADDR (default)'=>'Ninguna, usar REMOTE_ADDR (por defecto)','Operation Mode'=>'Modo de funcionamiento','Local Shield (recommended)'=>'Local Shield (recomendado)','Uses only your site\'s data. No external requests.'=>'Solo usa los datos de tu sitio. Sin peticiones externas.','Community Network (optional)'=>'Community Network (opcional)','Enabling Community Network mode will:'=>'Al activar el modo Community Network, el plugin:','Send blocked IP addresses to reportedip.com when your site detects an attack.'=>'Enviará las direcciones IP bloqueadas a reportedip.com cuando tu sitio detecte un ataque.','Query reportedip.com during login attempts to check IP reputation.'=>'Consultará reportedip.com durante los intentos de inicio de sesión para comprobar la reputación de la IP.','Send only the IP address, a category ID and a short comment with each report. Usernames never leave your server, neither in plain text nor hashed.'=>'Enviará solo la dirección IP, un ID de categoría y un breve comentario con cada informe. Los nombres de usuario nunca salen de tu servidor, ni en texto plano ni en hash.','Identify your site only via your Community Access Key — no domain or contact information is transmitted.'=>'Identificará tu sitio únicamente mediante tu Community Access Key. No se transmite ningún dominio ni dato de contacto.','Legal basis: GDPR Art. 6(1)(f), legitimate interest in network security.'=>'Base legal: art. 6.1.f del RGPD, interés legítimo en la seguridad de la red.','Community Access Key'=>'Community Access Key','Access Key'=>'Clave de acceso','Need an access key? Visit reportedip.com.'=>'¿Necesitas una clave de acceso? Visita reportedip.com.','API Endpoint'=>'Endpoint de la API','Default endpoint. Override via the reportedip_hive_api_endpoint filter.'=>'Endpoint por defecto. Puedes cambiarlo con el filtro reportedip_hive_api_endpoint.','Test connection'=>'Probar conexión','Reverse Proxy'=>'Proxy inverso','Trusted Proxy Header'=>'Cabecera de proxy de confianza','Only set this if your site sits behind a reverse proxy (Cloudflare, AWS, NGINX) that overrides the header for every incoming request. Otherwise the header can be spoofed.'=>'Configúralo solo si tu sitio está detrás de un proxy inverso (Cloudflare, AWS, NGINX) que sobrescribe la cabecera en cada petición entrante. De lo contrario, la cabecera puede falsificarse.','Brute-force thresholds'=>'Umbrales de fuerza bruta','Failed-login threshold'=>'Umbral de inicios de sesión fallidos','Block an IP after this many failed login attempts.'=>'Bloquea una IP tras este número de intentos de inicio de sesión fallidos.','Time window (minutes)'=>'Ventana de tiempo (minutos)','Time window during which failed attempts are counted.'=>'Ventana de tiempo durante la que se cuentan los intentos fallidos.','Password-spray detection'=>'Detección de password spraying (rociado de contraseñas)','Distinct usernames threshold'=>'Umbral de nombres de usuario distintos','Block an IP that fails logins against this many distinct usernames.'=>'Bloquea una IP que falla el inicio de sesión con este número de nombres de usuario distintos.','Blocking behaviour'=>'Comportamiento de bloqueo','Automatic blocking'=>'Bloqueo automático','If disabled, attempts are logged but no block is enforced (report-only mode).'=>'Si está desactivado, los intentos se registran pero no se aplica ningún bloqueo (modo solo informe).','Progressive block duration'=>'Duración de bloqueo progresiva','Increases block duration with each repeat offense (5 min → 15 min → 30 min → 24 h → 48 h → 7 days).'=>'Aumenta la duración del bloqueo con cada reincidencia (5 min → 15 min → 30 min → 24 h → 48 h → 7 días).','Report-only mode'=>'Modo solo informe','Detect and report attacks but never block. Useful for staging environments.'=>'Detecta e informa de los ataques, pero nunca bloquea. Útil para entornos de staging.','Show advanced (block ladder)'=>'Mostrar opciones avanzadas (escala de bloqueo)','Block ladder (CSV minutes)'=>'Escala de bloqueo (minutos en CSV)','Cache & retention'=>'Caché y conservación','Reputation cache duration (hours)'=>'Duración de la caché de reputación (horas)','Negative cache duration (hours)'=>'Duración de la caché negativa (horas)','API queue retention (days)'=>'Conservación de la cola de la API (días)','Uninstall'=>'Desinstalar','Delete all data on uninstall'=>'Borrar todos los datos al desinstalar','Drop all plugin tables and options when the plugin is deleted. Recommended OFF for forensic reasons.'=>'Elimina todas las tablas y opciones del plugin cuando se borra el plugin. Recomendado DESACTIVADO por motivos forenses.','Privacy notice'=>'Aviso de privacidad','This plugin processes IP addresses to detect attacks. Username inputs are stored hashed (SHA-256, salted with wp_salt()), never in plaintext. In Local Shield mode, no data leaves your server. In Community Network mode, blocked IP addresses are shared with reportedip.com together with an event category and a short comment; usernames are never transmitted. See the readme.txt "External services" and "Privacy" sections for full details.'=>'Este plugin procesa direcciones IP para detectar ataques. Los nombres de usuario introducidos se guardan como hash (SHA-256, con sal de wp_salt()), nunca en texto plano. En el modo Local Shield, ningún dato sale de tu servidor. En el modo Community Network, las direcciones IP bloqueadas se comparten con reportedip.com junto con una categoría de evento y un breve comentario; los nombres de usuario nunca se transmiten. Consulta las secciones "External services" y "Privacy" del readme.txt para más detalles.','No blocked IPs yet'=>'Todavía no hay IP bloqueadas','When the plugin blocks an attacker, you will see them listed here. Configure thresholds in Settings → Protection.'=>'Cuando el plugin bloquee a un atacante, aparecerá aquí. Configura los umbrales en Ajustes → Protección.','Configure Protection'=>'Configurar protección','Hive Light is complete and stays free. Need a Web Application Firewall, two-factor authentication or multisite support? The free Full Edition and the optional Hive PRO subscription build on the same engine.'=>'Hive Light está completo y seguirá siendo gratuito. ¿Necesitas un firewall de aplicaciones web, autenticación en dos pasos o compatibilidad con multisitio? La Full Edition gratuita y la suscripción opcional Hive PRO se basan en el mismo motor.','ReportedIP Hive Full Edition & PRO'=>'ReportedIP Hive Full Edition & PRO','Security Focused'=>'Security Focused','GDPR Compliant'=>'GDPR Compliant','Made in Germany'=>'Made in Germany','Settings saved.'=>'Ajustes guardados.','IP Address'=>'Dirección IP','Type'=>'Tipo','Count'=>'Cantidad','Last attempt'=>'Último intento','%s ago'=>'hace %s','Reason'=>'Motivo','Attempts'=>'Intentos','Blocked until'=>'Bloqueado hasta','Status'=>'Estado','Unblock selected'=>'Desbloquear seleccionadas','Never expires'=>'No caduca nunca','Expired'=>'Caducado','in %s'=>'en %s','Inactive'=>'Inactivo','Active'=>'Activo','ReportedIP Hive Light Setup'=>'Configuración de ReportedIP Hive Light','Setup'=>'Configuración','Welcome'=>'Bienvenida','Done'=>'Listo','Skip setup'=>'Omitir configuración','Setup progress'=>'Progreso de la configuración','Welcome to ReportedIP Hive Light'=>'Te damos la bienvenida a ReportedIP Hive Light','This short setup configures the brute-force counter and lets you choose whether the plugin should also consult the reportedip.com community database during login attempts.'=>'Esta breve configuración ajusta el contador de fuerza bruta y te permite elegir si el plugin debe consultar también la base de datos de la comunidad de reportedip.com durante los intentos de inicio de sesión.','You can change everything later under Settings → ReportedIP Hive Light.'=>'Puedes cambiarlo todo más adelante en Ajustes → ReportedIP Hive Light.','Get started'=>'Empezar','Checks IP reputation against the reportedip.com community database during login attempts and shares blocked IPs back. Usernames are never sent.'=>'Comprueba la reputación de la IP en la base de datos de la comunidad de reportedip.com durante los intentos de inicio de sesión y comparte a cambio las IP bloqueadas. Los nombres de usuario nunca se envían.','Community Access Key (optional)'=>'Community Access Key (opcional)','Required only for Community Network. A free key is available at reportedip.com.'=>'Solo es necesaria para Community Network. Puedes conseguir una clave gratuita en reportedip.com.','Continue'=>'Continuar','Protection settings'=>'Ajustes de protección','Enable automatic blocking'=>'Activar el bloqueo automático','When disabled, attempts are logged but no block is enforced.'=>'Si está desactivado, los intentos se registran pero no se aplica ningún bloqueo.','You are protected.'=>'Estás protegido.','ReportedIP Hive Light is active and listening to login attempts. Visit Settings → ReportedIP Hive Light any time to fine-tune thresholds, manage the whitelist, or review blocked IPs.'=>'ReportedIP Hive Light está activo y vigila los intentos de inicio de sesión. Visita Ajustes → ReportedIP Hive Light cuando quieras para ajustar los umbrales, gestionar la whitelist o revisar las IP bloqueadas.','Try a wrong-password login a few times to see the protection trigger.'=>'Prueba a iniciar sesión varias veces con una contraseña incorrecta para ver cómo se activa la protección.','Whitelist your office IP under Whitelist before any security drills.'=>'Añade la IP de tu oficina en Whitelist antes de hacer cualquier simulacro de seguridad.','Review the Privacy notice in Settings → Privacy if you intend to enable Community Network mode.'=>'Revisa el aviso de privacidad en Ajustes → Privacidad si piensas activar el modo Community Network.','Open dashboard'=>'Abrir el escritorio','IP / CIDR'=>'IP / CIDR','Expires'=>'Caduca','Added by'=>'Añadido por','Added'=>'Añadido','Remove selected'=>'Eliminar seleccionadas','(none)'=>'(ninguno)','Never'=>'Nunca','(system)'=>'(sistema)','No access key provided.'=>'No se ha indicado ninguna clave de acceso.','Could not reach reportedip.com: %s'=>'No se ha podido conectar con reportedip.com: %s','Connection successful. Your access key is valid.'=>'Conexión correcta. Tu clave de acceso es válida.','Connection failed: invalid access key. Check the key and try again.'=>'Error de conexión: clave de acceso no válida. Comprueba la clave e inténtalo de nuevo.','Connection failed (HTTP %d). Please retry in a few minutes.'=>'Error de conexión (HTTP %d). Vuelve a intentarlo dentro de unos minutos.','Every 15 minutes'=>'Cada 15 minutos','Access denied. Your IP address has been temporarily blocked due to suspicious activity.'=>'Acceso denegado. Tu dirección IP se ha bloqueado temporalmente por actividad sospechosa.','Access denied. This IP address has been flagged by the community.'=>'Acceso denegado. La comunidad ha marcado esta dirección IP.','Full Edition & PRO'=>'Full Edition & PRO','Access denied'=>'Acceso denegado','This plugin processes IP addresses to detect brute-force login attacks against your site. IP addresses are stored in the site database and may be displayed in the WordPress admin under "ReportedIP Hive Light → Blocked IPs".'=>'Este plugin procesa direcciones IP para detectar ataques de fuerza bruta contra el inicio de sesión de tu sitio. Las direcciones IP se guardan en la base de datos del sitio y pueden mostrarse en la administración de WordPress, en "ReportedIP Hive Light → IP bloqueadas".','Usernames submitted to the login form are stored as a SHA-256 hash, salted with the site\'s wp_salt(). Usernames are never transmitted, neither in plain text nor hashed.'=>'Los nombres de usuario enviados en el formulario de inicio de sesión se guardan como hash SHA-256, con la sal wp_salt() del sitio. Los nombres de usuario nunca se transmiten, ni en texto plano ni en hash.','In Local Shield mode (default), no data leaves your server. In Community Network mode, blocked IP addresses are shared with reportedip.com for collective threat intelligence, together with an event category and a short comment such as the number of failed logins. The site is identified only by the Community Access Key — no domain or contact information is transmitted.'=>'En el modo Local Shield (por defecto), ningún dato sale de tu servidor. En el modo Community Network, las direcciones IP bloqueadas se comparten con reportedip.com para la inteligencia colectiva sobre amenazas, junto con una categoría de evento y un breve comentario, como el número de inicios de sesión fallidos. El sitio se identifica únicamente mediante la Community Access Key. No se transmite ningún dominio ni dato de contacto.','ReportedIP Hive Light is active. <a href="%s">Configure protection</a> at Settings &rarr; ReportedIP Hive Light.'=>'ReportedIP Hive Light está activo. <a href="%s">Configura la protección</a> en Ajustes &rarr; ReportedIP Hive Light.','Dismiss notice'=>'Descartar aviso']];